package cn.enaium.elementplus.sample.gallery

/**
 * Source snippets shown by the gallery's expandable "View source" panels.
 * Only examples up to 30 lines are included; complex examples link to the
 * whole Docs.kt file from the page header instead.
 */
internal object SampleDemoSources {
    private val sources: Map<String, Map<String, String>> = mapOf(
