            "Infinite scroll" to "ElScrollbar(\n    height = 240.dp,\n    distance = 20.dp,\n    onEndReached = { direction ->\n        if (direction == ElScrollbarDirection.Bottom) endlessCount += 5\n    },\n) {\n    Column(Modifier.fillMaxWidth().padding(end = 12.dp)) {\n        repeat(endlessCount) { index -> ScrollItem(\"Item \${index + 1}\", false) }\n    }\n}\nDemoHint(\"\$endlessCount items loaded\")",
            "Manual scroll" to "ElScrollbar(\n    height = 200.dp,\n    always = true,\n    state = manualState,\n    onScroll = { scrollTop, _ -> manualValue = scrollTop },\n) {\n    Column(Modifier.fillMaxWidth().padding(end = 12.dp)) {\n        repeat(20) { index -> ScrollItem(\"Item \${index + 1}\", false) }\n    }\n}\nElSlider(\n    value = manualValue.toDouble(),\n    onValueChange = { manualState.setScrollTop(it.toFloat()) },\n    min = 0.0,\n    max = manualState.maxScrollTop.toDouble().coerceAtLeast(1.0),\n    step = 1.0,\n    formatTooltip = { \"\${it.toInt()} px\" },\n)",
            "Max height" to "DemoRow {\n    ElButton(onClick = { count++ }, text = \"Add Item\")\n    ElButton(onClick = { if (count > 0) count-- }, text = \"Delete Item\")\n}\nElScrollbar(maxHeight = 200.dp, modifier = Modifier.fillMaxWidth()) {\n    Column(Modifier.fillMaxWidth().padding(end = 12.dp)) {\n        repeat(count) { index -> ScrollItem(\"Item \${index + 1}\", false) }\n    }\n}",
            "Scroll mask" to "ElRadioGroup(\n    options = listOf(\n        ElRadioOption(\"off\", \"Off\"),\n        ElRadioOption(\"all\", \"All\"),\n        ElRadioOption(\"top\", \"Top\"),\n        ElRadioOption(\"bottom\", \"Bottom\"),\n        ElRadioOption(\"left\", \"Left\"),\n        ElRadioOption(\"right\", \"Right\"),\n    ),\n    selected = mask,\n    onSelectedChange = { mask = it },\n)\nDemoHint(\"Vertical scrolling\")\nElScrollbar(height = 180.dp, mask = maskSet, modifier = Modifier.fillMaxWidth()) {\n    Column(Modifier.fillMaxWidth().padding(end = 12.dp)) {\n        repeat(20) { index -> ScrollItem(\"Item \${index + 1}\", false) }\n    }\n}\nDemoHint(\"Horizontal scrolling\")\nElScrollbar(horizontal = true, height = 80.dp, mask = maskSet, modifier = Modifier.fillMaxWidth()) {\n    Row(Modifier.padding(bottom = 12.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n        repeat(20) { index -> ScrollItem(\"Item \${index + 1}\", horizontal = true) }\n    }\n}",
            "Scroll on both axes" to "ElScrollbar(bothAxis = true, height = 180.dp, width = 320.dp) {\n    Column(Modifier.padding(8.dp)) {\n        repeat(12) { row ->\n            Row(\n                Modifier.padding(bottom = 6.dp),\n                horizontalArrangement = Arrangement.spacedBy(6.dp),\n            ) {\n                repeat(12) { column ->\n                    Box(\n                        Modifier\n                            .width(90.dp)\n                            .height(36.dp)\n                            .background(colors.light(ElType.Primary, 8), RoundedCornerShape(4.dp)),\n                        contentAlignment = Alignment.Center,\n                    ) { BasicText(\"\$row-\$column\", style = theme.typography.extraSmall) }\n                }\n            }\n        }\n    }\n}",
        ),
        "basic/SpaceDocs.kt" to mapOf(
            "Alignment" to "Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    listOf(\n        Alignment.Top to \"flex-start\",\n        Alignment.CenterVertically to \"center\",\n        Alignment.Bottom to \"flex-end\",\n    ).forEach { (alignment, label) ->\n        DemoHint(label)\n        ElSpace(verticalAlignment = alignment, spacing = 8.dp) {\n            ElText(\"string\", size = ElSize.Small)\n            ElButton(onClick = {}, text = \"button\", size = ElSize.Small)\n            ElCard(contentPadding = 6.dp) { BasicText(\"body\", style = theme.typography.extraSmall) }\n        }\n    }\n}",
            "Auto wrapping" to "ElSpace(wrap = true) {\n    repeat(10) { Item(\"Wrapped item \${it + 1}\") }\n}",
            "Basic spacing" to "Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    ElSpace(size = ElSpaceSize.Small) { repeat(3) { Item(\"Item \${it + 1}\") } }\n    ElSpace(size = ElSpaceSize.Default) { repeat(3) { Item(\"Item \${it + 1}\") } }\n    ElSpace(size = ElSpaceSize.Large) { repeat(3) { Item(\"Item \${it + 1}\") } }\n}",
            "Component spacer" to "ElSpace(\n    spacing = 10.dp,\n    spacer = { ElDivider(direction = ElDividerDirection.Vertical, modifier = Modifier.height(18.dp)) },\n) {\n    ElButton(onClick = {}, text = \"Button 1\")\n    ElButton(onClick = {}, text = \"Button 2\")\n}",
            "Control size" to "ElSpace(vertical = true, horizontalAlignment = Alignment.Start, spacing = 30.dp) {\n    ElRadioGroup(\n        options = listOf(\n            ElRadioOption(\"large\", \"Large\"),\n            ElRadioOption(\"default\", \"Default\"),\n            ElRadioOption(\"small\", \"Small\"),\n        ),\n        selected = when (controlSize) {\n            ElSpaceSize.Large -> \"large\"\n            ElSpaceSize.Default -> \"default\"\n            ElSpaceSize.Small -> \"small\"\n        },\n        onSelectedChange = {\n            controlSize = when (it) {\n                \"large\" -> ElSpaceSize.Large\n                \"default\" -> ElSpaceSize.Default\n                else -> ElSpaceSize.Small\n            }\n        },\n    )\n    ElSpace(wrap = true, size = controlSize) {\n        repeat(3) { index ->\n            Box(Modifier.width(160.dp)) { CardItem(\"Card \${index + 1}\") }\n        }\n    }\n}",
            "Customized size" to "ElSpace(spacing = 24.dp) { repeat(3) { Item(\"Custom\") } }",
            "Fill" to "DemoRow {\n    ElSwitch(checked = fill, onCheckedChange = { fill = it })\n    DemoHint(\"fill = \$fill\")\n}\nElSpace(fill = fill, wrap = true) {\n    repeat(3) { CardItem(\"Card name\") }\n}",
            "Fill ratio" to "DemoRow {\n    ElRadioGroup(\n        options = listOf(ElRadioOption(\"horizontal\", \"horizontal\"), ElRadioOption(\"vertical\", \"vertical\")),\n        selected = fillDirection,\n        onSelectedChange = { fillDirection = it },\n    )\n    DemoHint(\"fillRatio = \${fillRatio.toInt()}\")\n}\nElSlider(value = fillRatio, onValueChange = { fillRatio = it }, min = 10.0, max = 100.0, step = 5.0)\nElSpace(\n    fill = true,\n    wrap = true,\n    fillRatio = fillRatio.toFloat(),\n    vertical = fillDirection == \"vertical\",\n    modifier = Modifier.fillMaxWidth(),\n) {\n    repeat(5) { CardItem(\"Card name\") }\n}",
            "Horizontal and vertical size" to "ElSpace(spacing = 20.dp, verticalSpacing = 4.dp, wrap = true, modifier = Modifier.fillMaxWidth()) {\n    repeat(12) { Item(\"Item \${it + 1}\") }\n}",
            "Literal spacer" to "ElSpace(\n    spacing = 10.dp,\n    spacer = { BasicText(\"|\", style = theme.typography.base.copy(color = colors.textPlaceholder)) },\n) {\n    ElButton(onClick = {}, text = \"Button 1\")\n    ElButton(onClick = {}, text = \"Button 2\")\n}",
            "Spacer between items" to "ElSpace {\n    Item(\"Left\")\n    Box(Modifier.width(40.dp).height(1.dp).background(colors.border))\n    Item(\"Right\")\n}",
            "Vertical layout" to "ElSpace(vertical = true) {\n    repeat(3) { Item(\"Vertical \${it + 1}\") }\n}",
        ),
        "basic/SplitterDocs.kt" to mapOf(
            "Basic splitter" to "ElSplitter(\n    panels = listOf(\n        ElSplitterPanel(size = 120.dp),\n        ElSplitterPanel(min = 80.dp),\n    ),\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n) { index ->\n    PanelBox(\n        \"Panel \${index + 1}\",\n        if (index == 0) colors.light(ElType.Primary, 8) else colors.light(ElType.Success, 8),\n    )\n}",
            "Custom split bar" to "ElSplitter(\n    panels = listOf(ElSplitterPanel(), ElSplitterPanel(), ElSplitterPanel()),\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    splitBarContent = { index ->\n        Box(\n            Modifier.fillMaxSize().padding(vertical = 2.dp),\n            contentAlignment = Alignment.Center,\n        ) {\n            BasicText(\n                \"\${index + 1}\",\n                style = theme.typography.extraSmall.copy(color = colors.primary),\n            )\n        }\n    },\n) { index ->\n    PanelBox(\"Panel \${index + 1}\", colors.light(ElType.Primary, 7 + index))\n}",
            "Disable drag" to "DemoRow {\n    ElSwitch(\n        checked = resizable,\n        onCheckedChange = { resizable = it },\n        activeText = \"enable\",\n        inactiveText = \"disable\",\n        inlinePrompt = true,\n    )\n}\nElSplitter(\n    panels = listOf(\n        ElSplitterPanel(),\n        ElSplitterPanel(resizable = resizable),\n        ElSplitterPanel(),\n    ),\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n) { index ->\n    PanelBox(\n        if (index == 1) \"drag \${if (resizable) \"enable\" else \"disable\"}\" else \"Panel \${index + 1}\",\n        colors.light(ElType.Warning, 7 + index),\n    )\n}",
            "Lazy panel sizes" to "DemoRow {\n    ElSwitch(\n        checked = lazySplit,\n        onCheckedChange = { lazySplit = it },\n        activeText = \"enable\",\n        inactiveText = \"disable\",\n        inlinePrompt = true,\n    )\n    DemoHint(\"Resize the window to see the difference\")\n}\nElSplitter(\n    panels = listOf(\n        ElSplitterPanel(collapsible = true, min = 50.dp),\n        ElSplitterPanel(collapsible = true),\n        ElSplitterPanel(collapsible = true),\n    ),\n    lazy = lazySplit,\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n) { index ->\n    PanelBox(\"Panel \${index + 1}\", colors.light(ElType.Success, 7 + index))\n}",
            "Panel size" to "var size by remember { mutableStateOf(100f) }\nvar lastEvent by remember { mutableStateOf(\"drag a bar\") }\nElSplitter(\n    panels = listOf(\n        ElSplitterPanel(),\n        ElSplitterPanel(size = size.dp, min = 50.dp, max = 200.dp),\n        ElSplitterPanel(),\n    ),\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n    onResizeStart = { index, sizes ->\n        size = sizes.getOrElse(1) { size }\n        lastEvent = \"resizeStart(\$index)\"\n    },\n    onResize = { index, sizes ->\n        size = sizes.getOrElse(1) { size }\n        lastEvent = \"resize(\$index, \${sizes.map { it.toInt() }})\"\n    },\n    onResizeEnd = { index, sizes ->\n        size = sizes.getOrElse(1) { size }\n        lastEvent = \"resizeEnd(\$index)\"\n    },\n) { index ->\n    PanelBox(\n        if (index == 1) \"\${size.toInt()}px\" else \"Panel \${index + 1}\",\n        colors.light(ElType.Primary, 7 + index),\n    )\n}\nDemoHint(lastEvent)",
            "Vertical layout" to "ElSplitter(\n    panels = listOf(ElSplitterPanel(), ElSplitterPanel()),\n    direction = ElSplitterDirection.Vertical,\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n) { index ->\n    PanelBox(\"Row \${index + 1}\", colors.light(ElType.Warning, 8))\n}",
        ),
        "basic/TextDocs.kt" to mapOf(
            "Basic text" to "Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n    DemoRow {\n        ElText(\"Default\")\n        ElText(\"Primary\", type = ElType.Primary)\n        ElText(\"Success\", type = ElType.Success)\n        ElText(\"Warning\", type = ElType.Warning)\n        ElText(\"Danger\", type = ElType.Danger)\n        ElText(\"Info\", type = ElType.Info)\n    }\n    DemoRow {\n        ElText(\"Large\", size = ElSize.Large)\n        ElText(\"Default\")\n        ElText(\"Small\", size = ElSize.Small)\n    }\n}",
            "Decorations" to "DemoRow {\n    ElText(\"Bold\", bold = true)\n    ElText(\"Italic\", italic = true)\n    ElText(\"Underline\", underline = true)\n    ElText(\"Strikethrough\", strikethrough = true)\n    ElText(\"Mark\", mark = true)\n    ElText(\"Disabled\", disabled = true)\n}",
            "Ellipsis" to "ElText(\n    \"This is a long piece of text that should be truncated with an ellipsis when it exceeds the available width.\",\n    truncated = true,\n    lineClamp = 1,\n    modifier = Modifier.width(260.dp),\n)",
            "Line clamp" to "ElText(\n    \"Line clamp works on its own. \".repeat(8),\n    maxLines = 2,\n    modifier = Modifier.width(260.dp),\n)",
            "Mixed content" to "Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n    ElText { color ->\n        ElIcon(ElIcons.ElementPlus, size = 16.dp, tint = color)\n        Spacer(Modifier.width(4.dp))\n        BasicText(\"Element Plus\", style = LocalElTheme.current.typography.base.copy(color = color))\n    }\n    DemoRow {\n        ElText(\"Rate\")\n        ElText(\"★★★★★\", type = ElType.Warning, modifier = Modifier.padding(start = 6.dp))\n    }\n    ElText { color ->\n        BasicText(\n            \"This is text mixed icon \",\n            style = LocalElTheme.current.typography.base.copy(color = color),\n        )\n        ElIcon(ElIcons.Bell, size = 16.dp, tint = color)\n        BasicText(\n            \" and component \",\n            style = LocalElTheme.current.typography.base.copy(color = color),\n        )\n        ElButton(onClick = {}, text = \"Button\", size = ElSize.Small)\n    }\n}",
            "Override" to "ElText(\"Custom colored text\", color = LocalElTheme.current.colors.primary, bold = true)\nElText(\"Underlined text\", underline = true)\nElText(\"Marked text\", mark = true)",
            "Sizes" to "Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n    ElText(\"Large text\", size = ElSize.Large)\n    ElText(\"Default text\")\n    ElText(\"Small text\", size = ElSize.Small)\n}",
            "Tag" to "Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n    ElText(\"span\")\n    ElText(\"This is a paragraph.\", tag = ElTextTag.Paragraph)\n    ElText(\"Bold\", tag = ElTextTag.Bold)\n    ElText(\"Italic\", tag = ElTextTag.Italic)\n    ElText(\"Inserted\", tag = ElTextTag.Insert)\n    ElText(\"Deleted\", tag = ElTextTag.Delete)\n    ElText(\"Marked\", tag = ElTextTag.Mark)\n    DemoRow {\n        ElText(\"This is\")\n        ElText(\"subscript\", tag = ElTextTag.Sub, size = ElSize.Small)\n    }\n    DemoRow {\n        ElText(\"This is\")\n        ElText(\"superscript\", tag = ElTextTag.Sup, size = ElSize.Small)\n    }\n}",
            "Truncated" to "ElText(\n    text = \"This is a very long text that demonstrates the truncated property of ElText. It will be cut off with an ellipsis at the end of the available width.\",\n    truncated = true,\n)\nSpacer(Modifier.height(8.dp))\nElText(\n    text = \"Line clamp can show multiple lines. \".repeat(6),\n    lineClamp = 2,\n    truncated = true,\n)",
        ),
        "basic/TypographyDocs.kt" to mapOf(
            "Convention" to "Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n    BasicText(\"Primary text\", style = theme.typography.large.copy(color = colors.textPrimary))\n    BasicText(\"Regular text\", style = theme.typography.base.copy(color = colors.textRegular))\n    BasicText(\"Secondary text\", style = theme.typography.small.copy(color = colors.textSecondary))\n    BasicText(\"Disabled text\", style = theme.typography.small.copy(color = colors.textDisabled))\n}",
            "Font size convention" to "val rows = listOf(\n    \"Supplementary text\" to theme.typography.extraSmall,\n    \"Body (small)\" to theme.typography.small,\n    \"Body\" to theme.typography.base,\n    \"Small Title\" to theme.typography.medium,\n    \"Title\" to theme.typography.large,\n    \"Main Title\" to theme.typography.extraLarge,\n)\nColumn(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n    Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {\n        DemoHint(\"Level\")\n        DemoHint(\"Font size\")\n        DemoHint(\"Demo\")\n    }\n    rows.forEach { (level, style) ->\n        Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {\n            BasicText(level, Modifier.width(150.dp), style = theme.typography.extraSmall.copy(color = colors.textSecondary))\n            BasicText(\n                \"\${style.fontSize.value.toInt()} sp\",\n                Modifier.width(90.dp),\n                style = theme.typography.extraSmall.copy(color = colors.textSecondary),\n            )\n            BasicText(\"Build with Element\", style = style.copy(color = colors.textPrimary))\n        }\n    }\n}",
            "Font stacks" to "val stacks = listOf(\n    \"PingFang SC · Hiragino Sans GB · Microsoft YaHei\" to FontFamily.SansSerif,\n    \"Helvetica Neue · Helvetica · Arial\" to FontFamily.SansSerif,\n    \"Georgia · Times New Roman\" to FontFamily.Serif,\n    \"Menlo · Consolas · Courier New\" to FontFamily.Monospace,\n)\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    stacks.forEach { (label, family) ->\n        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {\n            BasicText(\n                label,\n                style = theme.typography.extraSmall.copy(color = colors.textSecondary),\n            )\n            BasicText(\n                \"Build with Element 构建更美好的产品\",\n                style = theme.typography.base.copy(color = colors.textPrimary, fontFamily = family),\n            )\n        }\n    }\n}",
            "Headings" to "Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n    ElTypography(\"Heading 1\", level = 1)\n    ElTypography(\"Heading 2\", level = 2)\n    ElTypography(\"Heading 3\", level = 3)\n    ElTypography(\"Heading 4\", level = 4)\n    ElTypography(\"Heading 5\", level = 5)\n    ElTypography(\"Heading 6\", level = 6)\n}",
            "Line height" to "val sample =\n    \"Element Plus typography follows a consistent rhythm so that dense paragraphs stay readable \" +\n        \"and long form content keeps a comfortable measure across the product.\"\nval ratios = listOf(\n    \"line-height: 1 · No line height\" to 1.0f,\n    \"line-height: 1.3 · Compact\" to 1.3f,\n    \"line-height: 1.5 · Regular\" to 1.5f,\n    \"line-height: 1.7 · Loose\" to 1.7f,\n)\nColumn(verticalArrangement = Arrangement.spacedBy(14.dp)) {\n    ratios.forEach { (label, ratio) ->\n        Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {\n            BasicText(label, style = theme.typography.extraSmall.copy(color = colors.textSecondary))\n            BasicText(\n                sample,\n                Modifier\n                    .fillMaxWidth()\n                    .padding(8.dp)\n                    .background(colors.fillLighter, RoundedCornerShape(4.dp)),\n                style = withLineHeight(theme.typography.base, ratio).copy(color = colors.textRegular),\n            )\n        }\n    }\n}",
            "Text and paragraphs" to "Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n    ElText(\"This is a paragraph of text using the default text component.\", type = ElType.Default)\n    ElParagraph(\n        \"Element Plus typography provides a consistent scale and supports semantic colors, \" +\n            \"truncation and inline decorations.\",\n    )\n    ElTitle(\"A title component\", level = 4)\n}",
        ),
        "config/ConfigProviderDocs.kt" to mapOf(
            "All locales" to "var locale by remember { mutableStateOf(ElLocales.en) }\nvar page by remember { mutableStateOf(1) }\nval options = remember { ElLocales.all.map { ElSelectOption(it.name, it.name) } }\nColumn(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    ElSelect(\n        value = locale.name,\n        onValueChange = { locale = ElLocales.byName(it ?: \"en\") },\n        options = options,\n        filterable = true,\n        modifier = Modifier.width(260.dp),\n    )\n    ElConfigProvider(locale = locale) {\n        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n            BasicText(\n                \"\${locale.name} · \${locale.select.placeholder} · \${locale.datePicker.selectDate}\",\n                style = LocalElTheme.current.typography.small.copy(color = LocalElTheme.current.colors.primary),\n            )\n            ElPagination(total = 100, currentPage = page, onCurrentPageChange = { page = it })\n            ElEmpty()\n        }\n    }\n}",
            "Card config" to "var shadow by remember { mutableStateOf(ElCardShadow.Always) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElRadioGroup(\n        options = listOf(\n            ElRadioOption(\"always\", \"always\"),\n            ElRadioOption(\"hover\", \"hover\"),\n            ElRadioOption(\"never\", \"never\"),\n        ),\n        selected = shadow.name.lowercase(),\n        onSelectedChange = {\n            shadow = when (it) {\n                \"hover\" -> ElCardShadow.Hover\n                \"never\" -> ElCardShadow.Never\n                else -> ElCardShadow.Always\n            }\n        },\n    )\n    ElConfigProvider(card = ElCardConfig(shadow = shadow)) {\n        ElCard(header = { BasicText(\"Card name\", style = LocalElTheme.current.typography.small) }) {\n            BasicText(\"Card desu!\", style = LocalElTheme.current.typography.small)\n        }\n    }\n}",
            "Dialog config" to "var alignCenter by remember { mutableStateOf(true) }\nvar visible by remember { mutableStateOf(false) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElSwitch(checked = alignCenter, onCheckedChange = { alignCenter = it }, activeText = \"alignCenter\")\n    ElConfigProvider(dialog = ElDialogConfig(alignCenter = alignCenter)) {\n        ElButton(onClick = { visible = true }, text = \"Open Dialog\", type = ElType.Primary)\n        ElDialog(visible = visible, onClose = { visible = false }, title = \"Dialog Title\") {\n            BasicText(\"Dialog Content\", style = LocalElTheme.current.typography.small)\n        }\n    }\n}",
            "Empty values" to "var value by remember { mutableStateOf<String?>(null) }\nvar cleared by remember { mutableStateOf(\"not cleared yet\") }\nElConfigProvider(emptyValues = listOf(null, \"\"), valueOnClear = null) {\n    ElSelect(\n        value = value,\n        onValueChange = {\n            value = it\n            cleared = if (it == null || it.isEmpty()) \"the empty value is: \$it\" else \"value: \$it\"\n        },\n        options = listOf(ElSelectOption(\"\", \"All\")) + (1..5).map { ElSelectOption(\"Option\$it\", \"Option\$it\") },\n        clearable = true,\n        placeholder = \"Select\",\n        modifier = Modifier.width(240.dp),\n    )\n}\nDemoHint(cleared)",
            "Locale" to "var page by remember { mutableStateOf(1) }\nColumn(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    BasicText(\"English\", style = LocalElTheme.current.typography.small)\n    ElPagination(total = 100, currentPage = page, onCurrentPageChange = { page = it })\n    ElConfigProvider(locale = ElLocale.Chinese) {\n        BasicText(\"中文\", style = LocalElTheme.current.typography.small)\n        ElPagination(total = 100, currentPage = page, onCurrentPageChange = { page = it })\n        ElEmpty()\n    }\n}",
            "Message config" to "val max = 3\nvar plain by remember { mutableStateOf(true) }\nvar placement by remember { mutableStateOf(ElMessagePlacement.Bottom) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    DemoRow {\n        DemoHint(\"max = \$max\")\n        ElSwitch(checked = plain, onCheckedChange = { plain = it }, activeText = \"plain\")\n        ElRadioGroup(\n            options = listOf(\n                ElRadioOption(\"top\", \"top\"),\n                ElRadioOption(\"bottom\", \"bottom\"),\n            ),\n            selected = if (placement == ElMessagePlacement.Bottom) \"bottom\" else \"top\",\n            onSelectedChange = {\n                placement = if (it == \"bottom\") ElMessagePlacement.Bottom else ElMessagePlacement.Top\n            },\n        )\n    }\n    ElConfigProvider(message = ElMessageConfig(max = max, plain = plain, placement = placement)) {\n        ElButton(onClick = { ElMessage.show(\"This is a message from the provider configuration.\") }, text = \"OPEN\")\n    }\n}",
            "Nested providers" to "ElConfigProvider(size = ElSize.Large) {\n    val outer = LocalElConfig.current\n    BasicText(\n        \"outer: size=\${outer.size?.name}, locale=\${outer.locale.name}\",\n        style = LocalElTheme.current.typography.small,\n    )\n    ElConfigProvider(locale = ElLocale.Chinese) {\n        val inner = LocalElConfig.current\n        BasicText(\n            \"inner: size=\${inner.size?.name}, locale=\${inner.locale.name}\",\n            style = LocalElTheme.current.typography.small.copy(color = LocalElTheme.current.colors.primary),\n        )\n        ElButton(onClick = {}, text = \"继承大小\")\n    }\n}",
            "Table config" to "var showOverflowTooltip by remember { mutableStateOf(true) }\nval rows = remember {\n    listOf(\n        ConfigProviderRow(\"2016-05-04\", \"Aleyna Kutzner\", \"Lohrbergstr. 86c, Süd Lilli, Saarland\"),\n        ConfigProviderRow(\"2016-05-03\", \"Helen Jacobi\", \"760 A Street, South Frankfield, Illinois\"),\n        ConfigProviderRow(\"2016-05-02\", \"Brandon Deckert\", \"Arnold-Ohletz-Str. 41a, Alt Malinascheid, Thüringen\"),\n    )\n}\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElCheckbox(\n        checked = showOverflowTooltip,\n        onCheckedChange = { showOverflowTooltip = it },\n        label = \"showOverflowTooltip\",\n    )\n    ElConfigProvider(table = ElTableConfig(showOverflowTooltip = showOverflowTooltip)) {\n        ElTable(\n            data = rows,\n            columns = listOf(\n                ElTableColumn(\"Date\", width = 120.dp, property = { it.date }),\n                ElTableColumn(\"Name\", width = 140.dp, property = { it.name }),\n                ElTableColumn(\"Address (inherited)\", width = 260.dp, property = { it.address }),\n            ),\n        )\n    }\n}",
            "Theme" to "var dark by remember { mutableStateOf(false) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElSwitch(checked = dark, onCheckedChange = { dark = it }, activeText = \"Dark\", inactiveText = \"Light\", inlinePrompt = true)\n    ElConfigProvider(theme = if (dark) ElTheme.Dark else ElTheme.Light) {\n        ElConfigProvider(locale = ElLocale.English) {\n            Row(\n                Modifier\n                    .fillMaxWidth()\n                    .background(LocalElTheme.current.colors.backgroundPage, RoundedCornerShape(6.dp))\n                    .padding(14.dp),\n                horizontalArrangement = Arrangement.spacedBy(10.dp),\n            ) {\n                ElButton(onClick = {}, text = \"Primary\", type = ElType.Primary)\n                ElButton(onClick = {}, text = \"Default\")\n                ElButton(onClick = {}, text = \"Danger\", type = ElType.Danger)\n            }\n        }\n    }\n}",
            "Usage" to "val config = LocalElConfig.current\nDemoRowSpaced {\n    ElText(\"Locale: \${config.locale.name}\", size = ElSize.Small)\n    ElText(\"Size: \${config.size?.name ?: \"Default\"}\", size = ElSize.Small)\n    ElText(\"Z-index: \${config.zIndex}\", size = ElSize.Small)\n    ElText(\"Namespace: \${config.namespace}\", size = ElSize.Small)\n}\nElConfigProvider(size = ElSize.Large, locale = ElLocale.Chinese) {\n    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n        BasicText(\"Large + zh-cn subtree\", style = LocalElTheme.current.typography.small.copy(color = LocalElTheme.current.colors.primary))\n        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n            ElButton(onClick = {}, text = \"确定\", type = ElType.Primary)\n            ElInput(value = input, onValueChange = { input = it }, placeholder = \"请输入内容\")\n        }\n    }\n}",
        ),
