            "Avatar group collapse" to "ElAvatarGroup(count = 5, collapseAvatars = true, maxCollapseAvatars = 3) { index ->\n    ElAvatar(\n        text = \"U\${index + 1}\",\n        background = colors.light(listOf(ElType.Primary, ElType.Success, ElType.Warning)[index % 3], 9),\n        color = colors.colorOf(listOf(ElType.Primary, ElType.Success, ElType.Warning)[index % 3]),\n    )\n}",
            "Avatar group collapse tooltip" to "ElAvatarGroup(\n    count = 5,\n    collapseAvatars = true,\n    maxCollapseAvatars = 2,\n    collapseAvatarsTooltip = true,\n) { index ->\n    ElAvatar(\n        text = \"U\${index + 1}\",\n        background = colors.light(listOf(ElType.Primary, ElType.Success, ElType.Warning)[index % 3], 9),\n        color = colors.colorOf(listOf(ElType.Primary, ElType.Success, ElType.Warning)[index % 3]),\n    )\n}",
            "Avatar group custom collapse" to "ElAvatarGroup(\n    count = 6,\n    collapseAvatars = true,\n    maxCollapseAvatars = 4,\n    shape = ElAvatarShape.Square,\n    collapseContent = { hidden, _ ->\n        BasicText(\n            \"+\$hidden\",\n            style = LocalElTheme.current.typography.small.copy(\n                color = colors.primary,\n                fontWeight = FontWeight.Medium,\n            ),\n        )\n    },\n) { index ->\n    ElAvatar(\n        text = \"U\${index + 1}\",\n        shape = ElAvatarShape.Square,\n        background = colors.light(ElType.Primary, 8),\n        color = colors.primary,\n    )\n}",
            "Basic usage" to "Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElAvatar(icon = ElIcons.User)\n    ElAvatar(text = \"EP\", background = colors.light(ElType.Primary, 8), color = colors.primary)\n    ElAvatar(painter = ColorPainter(colors.primary), contentDescription = \"Avatar\")\n}",
