            "Fit" to "Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElAvatar(\n        painter = ColorPainter(LocalElTheme.current.colors.primary),\n        modifier = Modifier.size(64.dp),\n        contentScale = ContentScale.Crop,\n    )\n    ElAvatar(\n        painter = ColorPainter(LocalElTheme.current.colors.success),\n        modifier = Modifier.size(64.dp),\n        contentScale = ContentScale.Fit,\n    )\n}",
            "Shapes and sizes" to "Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElAvatar(text = \"SM\", size = 28.dp)\n    ElAvatar(text = \"MD\", size = 40.dp)\n    ElAvatar(text = \"LG\", size = 56.dp)\n    ElAvatar(text = \"SQ\", size = 40.dp, shape = ElAvatarShape.Square, background = colors.light(ElType.Success, 8))\n}",
            "Types" to "Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElAvatar(icon = ElIcons.User)\n    ElAvatar(text = \"K\")\n    ElAvatar(painter = ColorPainter(LocalElTheme.current.colors.primary))\n}",
        ),
        "data/BadgeDocs.kt" to mapOf(
            "Basic usage" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(value = \"12\") { ElButton(onClick = {}, text = \"Messages\") }\n    ElBadge(value = \"3\") { ElButton(onClick = {}, text = \"Notifications\") }\n}",
            "Custom badge style" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(\n        value = \"5\",\n        badgeModifier = Modifier.border(2.dp, colors.white, RoundedCornerShape(50)),\n    ) { ElButton(onClick = {}, text = \"Bordered\") }\n    ElBadge(\n        value = \"hot\",\n        color = colors.warning,\n        badgeModifier = Modifier.border(1.dp, colors.danger, RoundedCornerShape(50)),\n    ) { ElButton(onClick = {}, text = \"Outlined\") }\n}",
            "Custom color" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(value = \"9\", color = colors.success) { ElButton(onClick = {}, text = \"Success\") }\n    ElBadge(value = \"!\", color = colors.warning) { ElButton(onClick = {}, text = \"Warning\") }\n}",
            "Custom content" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(value = \"new\") { ElButton(onClick = {}, text = \"Comments\") }\n    ElBadge(\n        value = \"99\",\n        badgeContent = { value ->\n            Row(\n                horizontalArrangement = Arrangement.spacedBy(3.dp),\n                verticalAlignment = Alignment.CenterVertically,\n            ) {\n                ElIcon(ElIcons.Message, size = 12.dp, tint = colors.white)\n                BasicText(\n                    value,\n                    style = LocalElTheme.current.typography.extraSmall.copy(color = colors.white),\n                )\n            }\n        },\n    ) { ElButton(onClick = {}, text = \"Messages\") }\n}",
            "Dot" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(isDot = true) { ElButton(onClick = {}, text = \"Updates\") }\n    ElBadge(value = \"new\", isDot = false) { ElButton(onClick = {}, text = \"News\") }\n}",
            "Max" to "Row(horizontalArrangement = Arrangement.spacedBy(24.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(value = \"200\", max = 99) { ElButton(onClick = {}, text = \"Inbox\") }\n    ElBadge(value = \"999\", max = 999) { ElButton(onClick = {}, text = \"Archive\") }\n}",
            "Offset" to "Row(horizontalArrangement = Arrangement.spacedBy(28.dp), verticalAlignment = Alignment.CenterVertically) {\n    ElBadge(value = \"3\", offsetX = 12.dp, offsetY = (-2).dp) {\n        ElButton(onClick = {}, text = \"Offset X\")\n    }\n    ElBadge(value = \"3\", offsetX = 0.dp, offsetY = 10.dp) {\n        ElButton(onClick = {}, text = \"Offset Y\")\n    }\n}",
            "Standalone" to "Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElBadge(value = \"1\")\n    ElBadge(value = \"25\", type = ElType.Success)\n    ElBadge(isDot = true)\n}",
        ),
        "data/CalendarDocs.kt" to mapOf(
            "Basic usage" to "var basic by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElCalendar(value = basic, onValueChange = { basic = it })\nDemoHint(\"Selected: \$basic\")",
            "Controller type" to "var controller by remember { mutableStateOf(\"button\") }\nvar controllerDate by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElRadioGroup(\n    options = listOf(\n        ElRadioOption(\"button\", \"Button\"),\n        ElRadioOption(\"select\", \"Select\"),\n    ),\n    selected = controller,\n    onSelectedChange = { controller = it },\n    button = true,\n    size = ElSize.Small,\n)\nElCalendar(\n    value = controllerDate,\n    onValueChange = { controllerDate = it },\n    controllerType = if (controller == \"select\") ElCalendarControllerType.Select else ElCalendarControllerType.Button,\n)",
            "Custom date cell" to "var custom by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElCalendar(\n    value = custom,\n    onValueChange = { custom = it },\n    dateCell = { date, selected, inMonth ->\n        val theme = LocalElTheme.current\n        Column(\n            Modifier.fillMaxSize().padding(4.dp),\n            horizontalAlignment = Alignment.End,\n            verticalArrangement = Arrangement.SpaceBetween,\n        ) {\n            BasicText(\n                date.day.toString(),\n                style = theme.typography.small.copy(\n                    color = when {\n                        !inMonth -> theme.colors.textDisabled\n                        selected -> theme.colors.primary\n                        else -> theme.colors.textRegular\n                    },\n                ),\n            )\n            if (date.day % 5 == 0) {\n                BasicText(\"Event\", style = theme.typography.extraSmall.copy(color = theme.colors.success))\n            }\n        }\n    },\n)",
            "Custom formatter" to "var formatterDate by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElCalendar(\n    value = formatterDate,\n    onValueChange = { formatterDate = it },\n    controllerType = ElCalendarControllerType.Select,\n    formatter = { value, type ->\n        when (type) {\n            ElCalendarLabelType.Year -> \"Year \$value\"\n            ElCalendarLabelType.Month -> locale.datePicker.months[value - 1]\n        }\n    },\n)\nDemoHint(\"The month select shows localized month names instead of numbers.\")",
            "Custom header" to "var headerDate by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElCalendar(\n    value = headerDate,\n    onValueChange = { headerDate = it },\n    header = { month, previous, next, today ->\n        Row(\n            Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),\n            verticalAlignment = Alignment.CenterVertically,\n        ) {\n            BasicText(\"\${month.year} / \${month.month.number}\", style = LocalElTheme.current.typography.base)\n            Spacer(Modifier.weight(1f))\n            ElButton(onClick = previous, text = \"Prev\", size = ElSize.Small)\n            Spacer(Modifier.width(6.dp))\n            ElButton(onClick = today, text = \"Today\", size = ElSize.Small)\n            Spacer(Modifier.width(6.dp))\n            ElButton(onClick = next, text = \"Next\", size = ElSize.Small)\n        }\n    },\n)",
            "Selectable range" to "var rangeDate by remember { mutableStateOf(LocalDate(2019, 3, 4)) }\nElCalendar(\n    value = rangeDate,\n    onValueChange = { rangeDate = it },\n    range = LocalDate(2019, 3, 4)..LocalDate(2019, 3, 24),\n)\nDemoHint(\"Selected: \$rangeDate — only 2019-03-04 to 2019-03-24 can be picked.\")",
            "Year navigation" to "var yearDate by remember { mutableStateOf(LocalDate(2026, 10, 26)) }\nElCalendar(\n    value = yearDate,\n    onValueChange = { yearDate = it },\n    headerContent = { scope ->\n        Column(\n            Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),\n            verticalArrangement = Arrangement.spacedBy(6.dp),\n        ) {\n            BasicText(\n                text = \"Custom header · \${scope.date.year} / \${scope.date.month.number}\",\n                style = LocalElTheme.current.typography.base,\n            )\n            Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {\n                ElButton(onClick = scope.prevYear, text = \"Previous Year\", size = ElSize.Small)\n                ElButton(onClick = scope.prevMonth, text = \"Previous Month\", size = ElSize.Small)\n                ElButton(onClick = scope.today, text = \"Today\", size = ElSize.Small)\n                ElButton(onClick = scope.nextMonth, text = \"Next Month\", size = ElSize.Small)\n                ElButton(onClick = scope.nextYear, text = \"Next Year\", size = ElSize.Small)\n            }\n        }\n    },\n)",
        ),
        "data/CardDocs.kt" to mapOf(
            "Basic usage" to "ElCard(\n    modifier = Modifier.width(360.dp),\n    header = { BasicText(\"Card name\", style = theme.typography.medium) },\n    footer = {\n        BasicText(\n            \"Footer content\",\n            style = theme.typography.small.copy(color = theme.colors.textSecondary),\n        )\n    },\n) {\n    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n        (1..4).forEach { BasicText(\"List item \$it\", style = theme.typography.base) }\n    }\n}",
            "Customized section styles" to "ElCard(\n    modifier = Modifier.width(360.dp),\n    headerModifier = Modifier.background(theme.colors.light(ElType.Primary, 9)),\n    footerModifier = Modifier.background(theme.colors.fillLight),\n    header = { BasicText(\"Card name\", style = theme.typography.medium) },\n    footer = {\n        BasicText(\n            \"Footer content\",\n            style = theme.typography.small.copy(color = theme.colors.textSecondary),\n        )\n    },\n) {\n    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n        (1..4).forEach { BasicText(\"List item \$it\", style = theme.typography.base) }\n    }\n}",
            "Shadow" to "Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {\n    ElCard(shadow = ElCardShadow.Always, modifier = Modifier.width(160.dp)) { BasicText(\"Always\") }\n    ElCard(shadow = ElCardShadow.Hover, modifier = Modifier.width(160.dp)) { BasicText(\"Hover\") }\n    ElCard(shadow = ElCardShadow.Never, modifier = Modifier.width(160.dp)) { BasicText(\"Never\") }\n}",
            "Simple card" to "ElCard(modifier = Modifier.width(280.dp)) {\n    BasicText(\"Simple card content\", style = theme.typography.base)\n}",
            "With images" to "ElCard(modifier = Modifier.width(300.dp)) {\n    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n        ElImage(\n            painter = ColorPainter(theme.colors.light(ElType.Primary, 7)),\n            modifier = Modifier.fillMaxWidth().height(120.dp),\n        )\n        BasicText(\"Image card\", style = theme.typography.medium)\n        BasicText(\"A short description under the image.\", style = theme.typography.small.copy(color = theme.colors.textSecondary))\n    }\n}",
        ),
        "data/CarouselDocs.kt" to mapOf(
            "Arrows" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    arrow = ElCarouselArrow.Always,\n    indicatorPosition = ElCarouselIndicatorPosition.Outside,\n) { Slide(it) }",
            "Auto height" to "val heights = listOf(120.dp, 190.dp, 90.dp)\nElCarousel(itemCount = 3, autoplay = false, autoHeight = true) { index ->\n    Box(\n        Modifier\n            .fillMaxWidth()\n            .height(heights[index])\n            .background(listOf(colors.primary, colors.success, colors.warning)[index % 3], RoundedCornerShape(6.dp)),\n        contentAlignment = Alignment.Center,\n    ) {\n        BasicText(\n            text = \"Slide \${index + 1} · \${heights[index].value.toInt()}dp\",\n            style = LocalElTheme.current.typography.medium.copy(color = Color.White),\n        )\n    }\n}\nDemoHint(\"Slides should use natural heights; fillMaxSize content cannot be measured automatically.\")",
            "Basic usage" to "ElCarousel(itemCount = 3, modifier = Modifier.fillMaxWidth().height(200.dp)) { Slide(it) }",
            "Card mode" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n    type = ElCarouselType.Card,\n    loop = false,\n) { Slide(it) }",
            "Card scale" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n    type = ElCarouselType.Card,\n    cardScale = 0.6f,\n    loop = false,\n) { Slide(it) }",
            "Change event" to "var current by remember { mutableIntStateOf(0) }\nvar previous by remember { mutableIntStateOf(0) }\nElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(180.dp),\n    onChange = { now, before ->\n        current = now\n        previous = before\n    },\n) { Slide(it) }\nDemoHint(\"Current: \${current + 1} · Previous: \${previous + 1}\")",
            "Custom interval" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    autoplay = true,\n    interval = 1500,\n    loop = false,\n    arrow = ElCarouselArrow.Hover,\n) { Slide(it) }",
            "Indicator trigger" to "var trigger by remember { mutableStateOf(ElCarouselTrigger.Hover.name) }\nElRadioGroup(\n    options = listOf(\n        ElRadioOption(ElCarouselTrigger.Hover.name, \"Hover\"),\n        ElRadioOption(ElCarouselTrigger.Click.name, \"Click\"),\n    ),\n    selected = trigger,\n    onSelectedChange = { trigger = it },\n    button = true,\n    size = ElSize.Small,\n)\nElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(180.dp),\n    autoplay = false,\n    trigger = if (trigger == ElCarouselTrigger.Click.name) ElCarouselTrigger.Click else ElCarouselTrigger.Hover,\n    indicatorPosition = ElCarouselIndicatorPosition.Outside,\n) { Slide(it) }",
            "Indicators" to "Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    ElCarousel(itemCount = 3, modifier = Modifier.fillMaxWidth().height(180.dp), indicatorPosition = ElCarouselIndicatorPosition.Outside) { Slide(it) }\n    ElCarousel(itemCount = 3, modifier = Modifier.fillMaxWidth().height(180.dp), indicatorPosition = ElCarouselIndicatorPosition.Inside) { Slide(it) }\n}",
            "Motion blur" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    interval = 1200,\n    motionBlur = true,\n) { Slide(it) }",
            "No indicators or arrows" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    arrow = ElCarouselArrow.Never,\n    indicatorPosition = ElCarouselIndicatorPosition.None,\n) { Slide(it) }",
            "Pause on hover" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n    autoplay = true,\n    interval = 1500,\n    pauseOnHover = true,\n) { Slide(it) }\nDemoHint(\"Autoplay stops while the pointer is over the carousel and resumes when it leaves.\")",
            "Vertical" to "ElCarousel(\n    itemCount = 3,\n    modifier = Modifier.width(360.dp).height(300.dp),\n    vertical = true,\n    autoplay = false,\n) { Slide(it) }",
        ),
        "data/CollapseDocs.kt" to mapOf(
            "Accordion" to "var accordion by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = accordion, onActiveChange = { accordion = it }, accordion = true) {\n    ElCollapseItem(\"1\", \"Panel one\") { BasicText(\"Panel one content\") }\n    ElCollapseItem(\"2\", \"Panel two\") { BasicText(\"Panel two content\") }\n    ElCollapseItem(\"3\", \"Panel three\") { BasicText(\"Panel three content\") }\n}",
            "Basic usage" to "var basic by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = basic, onActiveChange = { basic = it }) {\n    ElCollapseItem(\"1\", \"Consistency\") {\n        BasicText(\"Consistency makes products feel predictable.\", style = LocalElTheme.current.typography.base)\n    }\n    ElCollapseItem(\"2\", \"Feedback\") {\n        BasicText(\"Every action should produce visible feedback.\", style = LocalElTheme.current.typography.base)\n    }\n    ElCollapseItem(\"3\", \"Efficiency\") {\n        BasicText(\"Reduce the number of steps needed to finish a task.\", style = LocalElTheme.current.typography.base)\n    }\n}",
            "Before collapse guard" to "var allowed by remember { mutableStateOf(false) }\nvar names by remember { mutableStateOf(listOf(\"1\")) }\nRow(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {\n    DemoLabel(\"before collapse return\")\n    ElSwitch(checked = allowed, onCheckedChange = { allowed = it }, activeText = \"true\", inactiveText = \"false\")\n}\nElCollapse(\n    activeNames = names,\n    onActiveChange = { names = it },\n    beforeCollapse = { _, _ ->\n        delay(400)\n        allowed\n    },\n) {\n    ElCollapseItem(\"1\", \"Consistency\") { BasicText(\"Toggle the switch to allow collapsing.\") }\n    ElCollapseItem(\"2\", \"Feedback\") { BasicText(\"Panel two content\") }\n}",
            "Custom content" to "var basic by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = basic, onActiveChange = { basic = it }) {\n    ElCollapseItem(\"custom\", \"A form inside a panel\") {\n        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n            BasicText(\"Use the panel for settings or secondary content.\", style = LocalElTheme.current.typography.base)\n            ElButton(onClick = {}, text = \"Save\", type = ElType.Primary)\n        }\n    }\n}",
            "Custom icon and position" to "var names by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = names, onActiveChange = { names = it }) {\n    ElCollapseItem(\"1\", \"Icon at start\", icon = ElIcons.CaretBottom, iconPosition = ElCollapseIconPosition.Start) {\n        BasicText(\"Content for the start icon panel\")\n    }\n    ElCollapseItem(\"2\", \"Icon at end\", icon = ElIcons.CaretBottom, iconPosition = ElCollapseIconPosition.End) {\n        BasicText(\"Content for the end icon panel\")\n    }\n}",
            "Custom icon slot" to "var names by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = names, onActiveChange = { names = it }) {\n    ElCollapseItem(\n        \"1\",\n        \"Consistency\",\n        iconContent = { isActive ->\n            BasicText(\n                if (isActive) \"Expanded\" else \"Collapsed\",\n                style = LocalElTheme.current.typography.small.copy(color = LocalElTheme.current.colors.primary),\n            )\n        },\n    ) { BasicText(\"Content for the custom icon panel\") }\n    ElCollapseItem(\"2\", \"Feedback\") { BasicText(\"Content for the second panel\") }\n}",
            "Custom title" to "var names by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = names, onActiveChange = { names = it }) {\n    ElCollapseItem(\n        \"1\",\n        \"\",\n        titleContent = {\n            Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {\n                ElTag(\"New\", type = ElType.Success, size = ElSize.Small)\n                BasicText(\"Custom title\", style = LocalElTheme.current.typography.base)\n            }\n        },\n    ) { BasicText(\"Custom title content\") }\n    ElCollapseItem(\"2\", \"Panel two\") { BasicText(\"Panel two content\") }\n}",
            "Custom title with active state" to "var names by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = names, onActiveChange = { names = it }, accordion = true) {\n    ElCollapseItem(\n        \"1\",\n        \"\",\n        titleSlot = { isActive ->\n            Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically) {\n                BasicText(\n                    \"Consistency\",\n                    style = LocalElTheme.current.typography.base.copy(\n                        color = if (isActive) LocalElTheme.current.colors.primary else LocalElTheme.current.colors.textPrimary,\n                        fontWeight = FontWeight.Medium,\n                    ),\n                )\n                ElIcon(ElIcons.InfoFilled, size = 14.dp)\n            }\n        },\n    ) { BasicText(\"The title turns primary while this panel is active.\") }\n    ElCollapseItem(\"2\", \"Feedback\") { BasicText(\"Panel two content\") }\n}",
            "Disabled" to "var basic by remember { mutableStateOf(listOf(\"1\")) }\nElCollapse(activeNames = basic, onActiveChange = { basic = it }) {\n    ElCollapseItem(\"1\", \"Enabled\") { BasicText(\"Enabled content\") }\n    ElCollapseItem(\"2\", \"Disabled\", disabled = true) { BasicText(\"Disabled content\") }\n}",
