        "data/TableDocs.kt" to mapOf(
            "Basic usage" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", width = 140.dp, property = { it.name }),\n        ElTableColumn(\"Age\", width = 80.dp, property = { it.age }),\n        ElTableColumn(\"City\", width = 140.dp, property = { it.city }),\n    ),\n)",
            "Check strictly" to "data class StrictNode(val id: Int, val label: String, val children: List<StrictNode> = emptyList())\nval tree = listOf(\n    StrictNode(1, \"Root 1\", listOf(StrictNode(11, \"Child 1-1\"), StrictNode(12, \"Child 1-2\"))),\n    StrictNode(2, \"Root 2\"),\n)\nvar strict by remember { mutableStateOf(false) }\nvar selected by remember { mutableStateOf(setOf<Any>()) }\nDemoRow {\n    ElButton(text = if (strict) \"check-strictly = true\" else \"check-strictly = false\", onClick = { strict = !strict })\n    DemoHint(\"Selected: \${selected.size}\")\n}\nElTable(\n    data = tree,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.label }),\n    ),\n    children = { it.children },\n    rowKey = { it.id },\n    defaultExpandAll = true,\n    selection = true,\n    checkStrictly = strict,\n    selectedKeys = selected,\n    onSelectionChange = { selected = it },\n)",
            "Custom column" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", width = 140.dp, property = { it.name }),\n        ElTableColumn(\"Status\", width = 120.dp, cell = { row, _ ->\n            ElTag(\n                text = row.status,\n                type = if (row.status == \"Active\") ElType.Success else ElType.Warning,\n            )\n        }),\n    ),\n)",
            "Custom index" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Index\", type = cn.enaium.elementplus.components.ElTableColumnType.Index, index = { it * 2 }, width = 90.dp),\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n    ),\n    border = true,\n)",
            "Default sort" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }, sortable = true),\n        ElTableColumn(\"Age\", key = \"age\", property = { it.age }, sortable = true),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    state = rememberElTableState(ElTableSort(\"age\", ElTableSortOrder.Descending)),\n)",
            "Empty and loading" to "Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {\n    ElTable(\n        data = emptyList<PersonRow>(),\n        columns = listOf(ElTableColumn(\"Name\", property = { it.name })),\n    )\n    ElTable(\n        data = rows,\n        columns = listOf(ElTableColumn(\"Name\", property = { it.name })),\n        loading = true,\n    )\n}",
            "Expandable row" to "var expanded by remember { mutableStateOf(setOf<Any>(\"Alice\")) }\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"City\", property = { it.city }),\n        ElTableColumn(\"Status\", property = { it.status }),\n    ),\n    rowKey = { it.name },\n    expandedRowKeys = expanded,\n    onExpandedChange = { expanded = it },\n    expandContent = { row, _ ->\n        Box(Modifier.fillMaxWidth().padding(16.dp)) {\n            BasicText(\n                text = \"\${row.name} lives in \${row.city} and is currently \${row.status.lowercase()}.\",\n                style = LocalElTheme.current.typography.small.copy(color = LocalElTheme.current.colors.textRegular),\n            )\n        }\n    },\n)",
            "Fixed column and group header" to "data class Delivery(val date: String, val name: String, val zip: String, val state: String, val city: String, val address: String)\nval rows = remember {\n    (1..7).map {\n        Delivery(\"2016-05-0\${(it % 8) + 1}\", \"Tom\", \"CA 90036\", \"California\", \"Los Angeles\", \"No. 189, Grove St, Los Angeles\")\n    }\n}\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Date\", property = { it.date }),\n        ElTableColumn(\"Name\", width = 100.dp, property = { it.name }),\n        ElTableColumn(\"Zip\", width = 120.dp, property = { it.zip }),\n        ElTableColumn(\n            \"Address Info\",\n            fixed = ElTableFixed.Right,\n            children = listOf(\n                ElTableColumn(\"State\", width = 120.dp, property = { it.state }),\n                ElTableColumn(\"City\", width = 120.dp, property = { it.city }),\n                ElTableColumn(\"Address\", minWidth = 200.dp, property = { it.address }),\n            ),\n        ),\n    ),\n    height = 250.dp,\n    border = true,\n)",
            "Fixed column and header" to "ElTable(\n    data = rows + rows,\n    columns = listOf(\n        ElTableColumn(\"Date\", width = 150.dp, fixed = ElTableFixed.Left, property = { it.name }),\n        ElTableColumn(\"Name\", width = 120.dp, property = { it.name }),\n        ElTableColumn(\"City\", width = 120.dp, property = { it.city }),\n        ElTableColumn(\"Address\", width = 420.dp, property = { it.city }),\n        ElTableColumn(\n            \"Operations\",\n            width = 120.dp,\n            fixed = ElTableFixed.Right,\n            cell = { row, _ -> ElText(\"Edit \${row.name}\", type = ElType.Primary) },\n        ),\n    ),\n    height = 240.dp,\n    border = true,\n)",
            "Fixed columns" to "data class Ticket(val id: Int, val title: String, val owner: String, val area: String, val state: String)\nval tickets = remember {\n    (1..8).map { index ->\n        Ticket(index, \"Ticket \$index\", \"Owner \${index % 3 + 1}\", \"Area \${index % 4 + 1}\", if (index % 2 == 0) \"Open\" else \"Closed\")\n    }\n}\nElTable(\n    data = tickets,\n    columns = listOf(\n        ElTableColumn(\"ID\", width = 60.dp, fixed = ElTableFixed.Left, property = { it.id }),\n        ElTableColumn(\"Title\", width = 200.dp, property = { it.title }),\n        ElTableColumn(\"Owner\", width = 200.dp, property = { it.owner }),\n        ElTableColumn(\"Area\", width = 200.dp, property = { it.area }),\n        ElTableColumn(\n            \"State\",\n            width = 100.dp,\n            fixed = ElTableFixed.Right,\n            cell = { row, _ ->\n                ElTag(row.state, type = if (row.state == \"Open\") ElType.Danger else ElType.Info, size = ElSize.Small)\n            },\n        ),\n    ),\n    height = 260.dp,\n    border = true,\n    modifier = Modifier.width(640.dp),\n)",
            "Fixed height" to "ElTable(\n    data = rows + rows + rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    height = 180.dp,\n    stripe = true,\n)",
            "Grouped header" to "data class Delivery(val id: Int, val name: String, val address: String, val city: String, val zip: String)\nval deliveries = listOf(\n    Delivery(1, \"Alice\", \"No. 1 Road\", \"Chengdu\", \"610000\"),\n    Delivery(2, \"Bob\", \"No. 2 Road\", \"Shanghai\", \"200000\"),\n    Delivery(3, \"Charlie\", \"No. 3 Road\", \"Beijing\", \"100000\"),\n)\nElTable(\n    data = deliveries,\n    columns = listOf(\n        ElTableColumn(\"ID\", width = 80.dp, fixed = ElTableFixed.Left, property = { it.id }),\n        ElTableColumn(\n            \"Delivery\",\n            children = listOf(\n                ElTableColumn(\"Name\", property = { it.name }),\n                ElTableColumn(\"Address\", property = { it.address }),\n            ),\n        ),\n        ElTableColumn(\n            \"Location\",\n            children = listOf(\n                ElTableColumn(\"City\", property = { it.city }),\n                ElTableColumn(\"Zip\", property = { it.zip }),\n            ),\n        ),\n    ),\n    border = true,\n)",
            "Lazy tree" to "data class LazyNode(val id: String, val label: String)\nval roots = listOf(LazyNode(\"root\", \"Server\"), LazyNode(\"leaf\", \"Local\"))\nval scope = rememberCoroutineScope()\nElTable(\n    data = roots,\n    columns = listOf(ElTableColumn(\"Name\", property = { it.label })),\n    rowKey = { it.id },\n    hasChildren = { it.id == \"root\" },\n    lazy = true,\n    load = { _, resolve ->\n        scope.launch {\n            delay(300)\n            resolve(listOf(LazyNode(\"child-1\", \"Database\"), LazyNode(\"child-2\", \"Cache\")))\n        }\n    },\n)\nDemoHint(\"Expand Server to load its children.\")",
            "Rowspan and colspan" to "data class Stat(val name: String, val value: Int, val region: String, val note: String)\nval stats = listOf(\n    Stat(\"Alice\", 20, \"East\", \"Team A\"),\n    Stat(\"Bob\", 30, \"East\", \"Team A\"),\n    Stat(\"Charlie\", 40, \"West\", \"Team B\"),\n    Stat(\"Diana\", 50, \"West\", \"Team B\"),\n)\nElTable(\n    data = stats,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Value\", width = 100.dp, property = { it.value }, align = ElTextAlign.End),\n        ElTableColumn(\"Region\", property = { it.region }),\n        ElTableColumn(\"Note\", property = { it.note }),\n    ),\n    spanMethod = { _, rowIndex, columnIndex, _ ->\n        if (rowIndex == 0 && columnIndex == 0) ElTableCellSpan(rowSpan = 2, colSpan = 2) else null\n    },\n    border = true,\n)",
            "Selectable rows" to "var selected by remember { mutableStateOf(setOf<Any>()) }\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    rowKey = { it.name },\n    selection = true,\n    selectable = { row, _ -> row.age >= 30 },\n    selectedKeys = selected,\n    onSelectionChange = { selected = it },\n)\nDemoHint(\"Only rows aged 30 and above are selectable.\")",
            "Selection" to "var selected by remember { mutableStateOf(setOf<Any>()) }\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    selection = true,\n    selectedKeys = selected,\n    onSelectionChange = { selected = it },\n    rowKey = { it.name },\n)\nDemoRow {\n    ElButton(text = \"Clear selection\", onClick = { selected = emptySet() })\n    DemoHint(\"Selected: \${selected.size}\")\n}",
            "Single selection" to "var current by remember { mutableStateOf<Any?>(\"Bob\") }\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    rowKey = { it.name },\n    highlightCurrentRow = true,\n    selectedRowKey = current,\n    onRowClick = { row, _ -> current = row.name },\n)\nDemoHint(\"Current row: \${current ?: \"none\"}\")",
            "Sortable" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", key = \"name\", property = { it.name }, sortable = true),\n        ElTableColumn(\"Age\", key = \"age\", property = { it.age }, sortable = true, align = ElTextAlign.End),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n)",
            "Striped and border" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }),\n        ElTableColumn(\"City\", property = { it.city }),\n        ElTableColumn(\"Status\", property = { it.status }),\n    ),\n    stripe = true,\n    border = true,\n)",
            "Summary row" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"Age\", property = { it.age }, align = ElTextAlign.End),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    showSummary = true,\n    summaryMethod = { _, data -> listOf(\"Total\", data.sumOf { it.age }.toString(), \"\") },\n)",
            "Table layout" to "var layout by remember { mutableStateOf(ElTableLayout.Fixed) }\nDemoRow {\n    ElButton(text = if (layout == ElTableLayout.Fixed) \"layout: fixed\" else \"layout: auto\", onClick = {\n        layout = if (layout == ElTableLayout.Fixed) ElTableLayout.Auto else ElTableLayout.Fixed\n    })\n}\nElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\"Date\", property = { it.name }),\n        ElTableColumn(\"Name\", property = { it.name }),\n        ElTableColumn(\"City\", property = { it.city }),\n    ),\n    tableLayout = layout,\n    border = true,\n)",
            "Table with status" to "data class Order(val id: Int, val name: String, val status: String)\nval orders = listOf(\n    Order(1, \"Order A\", \"Success\"),\n    Order(2, \"Order B\", \"Pending\"),\n    Order(3, \"Order C\", \"Failed\"),\n)\nElTable(\n    data = orders,\n    columns = listOf(\n        ElTableColumn(\"ID\", width = 80.dp, property = { it.id }),\n        ElTableColumn(\"Name\", width = 180.dp, property = { it.name }),\n        ElTableColumn(\n            \"Status\",\n            width = 120.dp,\n            cell = { row, _ ->\n                ElTag(\n                    text = row.status,\n                    type = when (row.status) {\n                        \"Success\" -> ElType.Success\n                        \"Pending\" -> ElType.Warning\n                        else -> ElType.Danger\n                    },\n                    size = ElSize.Small,\n                )\n            },\n        ),\n    ),\n)",
            "Tooltip" to "ElTable(\n    data = rows,\n    columns = listOf(\n        ElTableColumn(\n            \"Description\",\n            width = 260.dp,\n            property = { \"\${it.name} is a resident of \${it.city}. This description is intentionally long to demonstrate overflow tooltips.\" },\n            showOverflowTooltip = true,\n            tooltipFormatter = { data -> \"Row \${data.rowIndex + 1}: \${data.cellValue}\" },\n        ),\n        ElTableColumn(\"Age\", width = 80.dp, property = { it.age }),\n    ),\n    showOverflowTooltip = false,\n)",
            "Tree data" to "data class Node(val id: String, val label: String, val size: Int, val children: List<Node> = emptyList())\nval tree = listOf(\n    Node(\n        \"1\", \"Root\", 100, listOf(\n            Node(\"1-1\", \"Child 1\", 40),\n            Node(\"1-2\", \"Child 2\", 60),\n        ),\n    ),\n    Node(\"2\", \"Other\", 80),\n)\nvar selected by remember { mutableStateOf(setOf<Any>()) }\nElTable(\n    data = tree,\n    columns = listOf(\n        ElTableColumn(\"Name\", property = { it.label }),\n        ElTableColumn(\"Size\", width = 100.dp, property = { it.size }, align = ElTextAlign.End),\n    ),\n    children = { it.children },\n    rowKey = { it.id },\n    defaultExpandAll = true,\n    selection = true,\n    selectedKeys = selected,\n    onSelectionChange = { selected = it },\n)\nDemoHint(\"Checked nodes: \${selected.joinToString()}\")",
        ),
        "data/TagDocs.kt" to mapOf(
            "Basic usage" to "DemoRow {\n    ElTag(\"Primary\")\n    ElTag(\"Success\", type = ElType.Success)\n    ElTag(\"Info\", type = ElType.Info)\n    ElTag(\"Warning\", type = ElType.Warning)\n    ElTag(\"Danger\", type = ElType.Danger)\n}",
            "Checkable tag" to "var checked by remember { mutableStateOf(true) }\nElTag(\n    text = if (checked) \"Checked\" else \"Unchecked\",\n    type = if (checked) ElType.Primary else ElType.Info,\n    effect = if (checked) ElTagEffect.Dark else ElTagEffect.Light,\n    onClick = { checked = !checked },\n)",
            "Custom color" to "DemoRow {\n    ElTag(\"Custom\", color = colors.warning)\n    ElTag(\"Green\", color = colors.success)\n    ElTag(\"Purple\", color = Color(0xFF8E44AD))\n}",
            "Editable" to "var tags by remember { mutableStateOf(listOf(\"Tag 1\", \"Tag 2\", \"Tag 3\")) }\nvar adding by remember { mutableStateOf(false) }\nvar input by remember { mutableStateOf(\"\") }\nfun commit() {\n    if (input.isNotBlank()) tags = tags + input.trim()\n    input = \"\"\n    adding = false\n}\nDemoRow {\n    tags.forEach { tag ->\n        ElTag(text = tag, closable = true, onClose = { tags = tags - tag })\n    }\n    if (adding) {\n        ElInput(\n            value = input,\n            onValueChange = { input = it },\n            placeholder = \"new tag\",\n            size = ElSize.Small,\n            autofocus = true,\n            onKeyboardAction = { commit() },\n            modifier = Modifier.width(120.dp),\n        )\n    } else {\n        ElButton(text = \"+ New Tag\", size = ElSize.Small, onClick = { adding = true })\n    }\n}",
            "Effects" to "DemoRow {\n    ElTag(\"Light\", effect = ElTagEffect.Light)\n    ElTag(\"Dark\", effect = ElTagEffect.Dark)\n    ElTag(\"Plain\", type = ElType.Success, effect = ElTagEffect.Plain)\n}",
            "Removable" to "var tags by remember { mutableStateOf(listOf(\"Kotlin\", \"Compose\", \"Multiplatform\")) }\nDemoRow {\n    tags.forEach { tag ->\n        ElTag(\n            text = tag,\n            closable = true,\n            onClose = { tags = tags - tag },\n        )\n    }\n}",
            "Rounded and sizes" to "DemoRow {\n    ElTag(\"Round\", round = true)\n    ElTag(\"Large\", size = ElSize.Large)\n    ElTag(\"Small\", size = ElSize.Small)\n}",
        ),
