        "data/TreeDocs.kt" to mapOf(
            "Accordion" to "ElTree(\n    data = data,\n    accordion = true,\n    modifier = Modifier.width(340.dp),\n)\nDemoHint(\"Only one sibling branch stays open at each level.\")",
            "Basic usage" to "var clicked by remember { mutableStateOf<String?>(null) }\nElTree(\n    data = data,\n    onNodeClick = { clicked = it.label },\n    modifier = Modifier.width(340.dp),\n)\nDemoHint(\"Clicked: \${clicked ?: \"-\"}\")",
            "Checking tree nodes" to "var checked by remember { mutableStateOf(setOf(\"5\", \"9\")) }\nvar hint by remember { mutableStateOf(\"\") }\nElTree(\n    data = treeDefaultData(),\n    checkedKeys = checked,\n    onCheckedChange = { checked = it },\n    showCheckbox = true,\n    defaultExpandAll = true,\n    highlightCurrent = true,\n    modifier = Modifier.width(340.dp),\n)\nDemoRow {\n    ElButton(text = \"Get checked\", size = ElSize.Small, onClick = {\n        hint = checked.sorted().joinToString()\n    })\n    ElButton(text = \"Set node 5\", size = ElSize.Small, onClick = {\n        checked = setOf(\"5\")\n        hint = \"checked = [5]\"\n    })\n    ElButton(text = \"Set keys 3\", size = ElSize.Small, onClick = {\n        checked = setOf(\"3\", \"7\", \"8\")\n        hint = \"checked = [3, 7, 8]\"\n    })\n    ElButton(text = \"Reset\", size = ElSize.Small, onClick = {\n        checked = emptySet()\n        hint = \"checked = []\"\n    })\n}\nDemoHint(if (hint.isBlank()) \"Checked keys: \${checked.sorted().joinToString()}\" else hint)",
            "Custom leaf node in lazy mode" to "val scope = rememberCoroutineScope()\nElTree(\n    data = emptyList(),\n    lazy = true,\n    showCheckbox = true,\n    modifier = Modifier.width(340.dp),\n    load = { node, resolve, _ ->\n        if (node == null) {\n            resolve(listOf(ElTreeNode(\"region\", \"region\")))\n        } else {\n            scope.launch {\n                delay(350)\n                when (node.key) {\n                    \"region\" -> resolve(\n                        listOf(\n                            ElTreeNode(\"leaf\", \"leaf\", leaf = true),\n                            ElTreeNode(\"zone\", \"zone\"),\n                        ),\n                    )\n                    else -> resolve(\n                        listOf(ElTreeNode(\"\${node.key}-leaf\", \"\${node.key} leaf\", leaf = true)),\n                    )\n                }\n            }\n        }\n    },\n)\nDemoHint(\"Expand region; leaf has no arrow.\")",
            "Custom node class" to "ElTree(\n    data = treeClassData(),\n    showCheckbox = true,\n    defaultExpandAll = true,\n    expandOnClickNode = false,\n    nodeModifier = { node ->\n        if (node.key in setOf(\"2\", \"3\", \"4\")) {\n            Modifier.background(colors.primary.copy(alpha = 0.10f), RoundedCornerShape(4.dp))\n        } else {\n            Modifier\n        }\n    },\n    modifier = Modifier.width(360.dp),\n)",
            "Default expanded and default checked" to "ElTree(\n    data = treeDefaultData(),\n    showCheckbox = true,\n    defaultExpandedKeys = setOf(\"2\", \"3\"),\n    defaultCheckedKeys = setOf(\"5\"),\n    modifier = Modifier.width(340.dp),\n)",
            "Disabled checkbox" to "var checked by remember { mutableStateOf(emptySet<String>()) }\nElTree(\n    data = treeDisabledData(),\n    checkedKeys = checked,\n    onCheckedChange = { checked = it },\n    showCheckbox = true,\n    defaultExpandAll = true,\n    modifier = Modifier.width(360.dp),\n)",
            "Draggable" to "var dragData by remember { mutableStateOf(treeDraggableData()) }\nvar lastDrop by remember { mutableStateOf(\"\") }\nElTree(\n    data = dragData,\n    onDataChange = { dragData = it },\n    draggable = true,\n    defaultExpandAll = true,\n    allowDrag = { node -> !node.label.contains(\"Level three 3-1-1\") },\n    allowDrop = { _, drop, type ->\n        if (drop.label == \"Level two 3-1\") type != ElTreeNodeDropType.Inner else true\n    },\n    onNodeDrop = { dragging, drop, type ->\n        lastDrop = \"\${dragging.label} -> \${drop.label} (\${type.name})\"\n    },\n    modifier = Modifier.width(400.dp),\n)\nDemoHint(lastDrop.ifBlank { \"Drag a node to reorder it.\" })",
            "Selectable" to "var selected by remember { mutableStateOf<String?>(\"1-1\") }\nElTree(\n    data = data,\n    selectedKey = selected,\n    onSelectedChange = { selected = it },\n    highlightCurrent = true,\n    expandOnClickNode = false,\n    defaultExpandAll = true,\n    modifier = Modifier.width(340.dp),\n)\nDemoHint(\"Selected: \${selected ?: \"-\"}\")",
            "Tree node filtering" to "var filter by remember { mutableStateOf(\"\") }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElInput(\n        value = filter,\n        onValueChange = { filter = it },\n        placeholder = \"Filter keyword\",\n        clearable = true,\n        modifier = Modifier.width(260.dp),\n    )\n    ElTree(\n        data = data,\n        filterText = filter,\n        filterNodeMethod = { query, node -> node.label.contains(query, ignoreCase = true) },\n        defaultExpandAll = true,\n        modifier = Modifier.width(340.dp),\n    )\n}",
        ),
        "data/VirtualizedTableDocs.kt" to mapOf(
            "Auto resizer" to "Box(Modifier.fillMaxWidth().height(400.dp)) {\n    ElAutoResizer { width, height ->\n        ElVirtualizedTable(\n            data = rows.take(200),\n            columns = v2Columns(),\n            width = width,\n            height = height,\n        )\n    }\n}",
