            "Custom suggestion item" to "var value by remember { mutableStateOf(emptyList<String>()) }\nElCascader(\n    value = value,\n    onValueChange = { value = it },\n    options = guideOptions,\n    filterable = true,\n    placeholder = \"Try searching: Guide\",\n    suggestionContent = { _, path ->\n        val theme = LocalElTheme.current\n        BasicText(\n            text = \"🔍 \${path.joinToString(\" > \") { it.label }}\",\n            style = theme.typography.base.copy(color = theme.colors.primary),\n        )\n    },\n    modifier = Modifier.width(320.dp),\n)",
            "Disabled" to "ElCascader(\n    value = listOf(\"guangdong\", \"shenzhen\"),\n    onValueChange = {},\n    options = options,\n    disabled = true,\n    modifier = Modifier.width(280.dp),\n)",
