            "Multiple with checkboxes and collapsible tags" to "var checkedValue by remember { mutableStateOf(emptyList<String>()) }\nElTreeSelect(\n    selectedKey = null,\n    onSelectedChange = {},\n    data = nestedData,\n    multiple = true,\n    showCheckbox = true,\n    selectedKeys = checkedValue,\n    onSelectedKeysChange = { checkedValue = it },\n    maxCollapseTags = 2,\n    defaultExpandAll = true,\n    placeholder = \"Select nodes\",\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(\"\${checkedValue.size} node(s) checked\")",
            "Prop alias and node-key" to "var aliasValue by remember { mutableStateOf(listOf(\"2\")) }\nElTreeSelect(\n    selectedKey = null,\n    onSelectedChange = {},\n    data = treeAliasNodes.toTreeNodes(\n        ElTreeSelectProps(\n            key = { it.id.toString() },\n            label = { it.desc },\n            children = { it.childNodes },\n        ),\n    ),\n    multiple = true,\n    showCheckbox = true,\n    selectedKeys = aliasValue,\n    onSelectedKeysChange = { aliasValue = it },\n    defaultExpandAll = true,\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(\"Selected ids: \${aliasValue.joinToString(\", \").ifEmpty { \"-\" }}\")",
