        "form/UploadDocs.kt" to mapOf(
            "Basic usage" to "UploadSample()",
            "Before remove validation" to "var files by remember {\n    mutableStateOf(\n        listOf(\n            ElUploadFile(\"1\", \"report.pdf\", status = ElUploadStatus.Success, thumbnail = ColorPainter(Color(0xFF409EFF))),\n            ElUploadFile(\"2\", \"archive.locked\", status = ElUploadStatus.Success, thumbnail = ColorPainter(Color(0xFFF56C6C))),\n        )\n    )\n}\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {},\n    listType = ElUploadListType.Picture,\n    beforeRemove = { file ->\n        if (file.name.endsWith(\".locked\")) {\n            ElMessage.show(\"\${file.name} can not be removed\", ElMessageType.Warning)\n            false\n        } else {\n            true\n        }\n    },\n    tip = \"archive.locked can not be removed\",\n)",
            "Custom thumbnail" to "var files by remember {\n    mutableStateOf(listOf(ElUploadFile(\"1\", \"custom.png\", thumbnail = ColorPainter(Color(0xFFF56C6C)), status = ElUploadStatus.Success)))\n}\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {},\n    listType = ElUploadListType.Picture,\n)",
            "Directory upload" to "var files by remember { mutableStateOf(emptyList<ElUploadFile>()) }\nvar picked by remember { mutableStateOf(0) }\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {\n        picked += 1\n        files = files + listOf(\n            ElUploadFile(\"dir-\$picked-a\", \"assets/image-\$picked.png\", status = ElUploadStatus.Success, thumbnail = ColorPainter(Color(0xFF409EFF))),\n            ElUploadFile(\"dir-\$picked-b\", \"assets/readme-\$picked.md\", status = ElUploadStatus.Success),\n        )\n    },\n    drag = true,\n    directory = true,\n    multiple = true,\n    tip = \"Drop directory here or click to upload\",\n    tipContent = { DemoHint(\"Nested paths are preserved for directory uploads.\") },\n)",
            "Drag and drop" to "UploadSample(drag = true, limit = 5)",
            "File list with thumbnails" to "var files by remember {\n    mutableStateOf(\n        listOf(\n            ElUploadFile(\"1\", \"element-plus-logo.svg\", thumbnail = ColorPainter(Color(0xFF409EFF)), status = ElUploadStatus.Success, percentage = 100.0),\n            ElUploadFile(\"2\", \"guide.pdf\", thumbnail = ColorPainter(Color(0xFF67C23A)), status = ElUploadStatus.Uploading, percentage = 42.0),\n            ElUploadFile(\"3\", \"broken.docx\", thumbnail = ColorPainter(Color(0xFFF56C6C)), status = ElUploadStatus.Fail, error = \"Network error\"),\n        )\n    )\n}\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {},\n    listType = ElUploadListType.Picture,\n    tip = \"Existing files with status and thumbnails\",\n)",
            "Limit" to "UploadSample(limit = 2)",
            "Limit cover" to "var files by remember {\n    mutableStateOf(listOf(ElUploadFile(\"cover-0\", \"cover-0.pdf\", status = ElUploadStatus.Ready)))\n}\nvar coverIndex by remember { mutableStateOf(0) }\nval controller = remember { ElUploadController() }\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {},\n    limit = 1,\n    autoUpload = false,\n    controller = controller,\n    onExceed = {\n        controller.clearFiles()\n        coverIndex += 1\n        controller.handleStart(ElUploadFile(\"cover-\$coverIndex\", \"cover-\$coverIndex.pdf\", status = ElUploadStatus.Ready))\n    },\n    trigger = { BasicText(\"Select file\") },\n    tipContent = { DemoHint(\"Limit 1 file, a new file covers the old one.\") },\n)",
            "Manual upload" to "var files by remember { mutableStateOf(listOf(ElUploadFile(\"1\", \"manual.pdf\", status = ElUploadStatus.Ready))) }\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {},\n    onUploadFile = { file ->\n        files = files.map { if (it.uid == file.uid) it.copy(status = ElUploadStatus.Uploading, percentage = 50.0) else it }\n    },\n    tip = \"Click a pending file to upload\",\n)",
            "Picture card" to "UploadSample(listType = ElUploadListType.PictureCard)",
            "Plain text file list with on-change" to "var files by remember {\n    mutableStateOf(\n        listOf(\n            ElUploadFile(\"1\", \"food.jpeg\", status = ElUploadStatus.Success),\n            ElUploadFile(\"2\", \"food2.jpeg\", status = ElUploadStatus.Success),\n        )\n    )\n}\nvar picked by remember { mutableStateOf(0) }\nElUpload(\n    files = files,\n    onFilesChange = { files = it },\n    onPickFiles = {\n        picked += 1\n        files = files + ElUploadFile(\"plain-\$picked\", \"food-extra-\$picked.jpeg\", status = ElUploadStatus.Ready)\n    },\n    onChange = { _, list ->\n        if (list.size > 3) files = list.takeLast(3)\n    },\n    tip = \"Only the last three files are kept\",\n)",
        ),
        "form/VirtualizedSelectDocs.kt" to mapOf(
            "Aliases for custom options" to "val aliases = remember { (1..1000).map { VirtualAlias(\"id-\$it\", \"Alias \$it\") } }\nvar value by remember { mutableStateOf<String?>(null) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = remember(aliases) { elSelectOptions(aliases, { it.id }, { it.name }) },\n    filterable = true,\n    placeholder = \"Select\",\n    modifier = Modifier.width(280.dp),\n)",
            "Basic usage" to "var value by remember { mutableStateOf<String?>(null) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = options,\n    placeholder = \"Please select\",\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(\"Selected: \${value ?: \"-\"}\")",
            "Clearable selector" to "var value by remember { mutableStateOf<String?>(\"item-1\") }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = options,\n    clearable = true,\n    placeholder = \"Clearable\",\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(\"Selected: \${value ?: \"-\"}\")",
            "Create Option" to "var values by remember { mutableStateOf(emptyList<String>()) }\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = options.take(20),\n    filterable = true,\n    allowCreate = true,\n    defaultFirstOption = true,\n    onCreateOption = { ElSelectOption(it, it) },\n    placeholder = \"Type and press Enter\",\n    modifier = Modifier.width(300.dp),\n)",
            "Custom Label" to "val labelOptions = remember { options.take(20) }\nvar single by remember { mutableStateOf<String?>(\"item-1\") }\nvar multiple by remember { mutableStateOf(listOf(\"item-1\")) }\nval labelContent: @Composable (String, String, ElSelectOption<String>) -> Unit = { label, value, _ ->\n    BasicText(\"\$label: \$value\", style = theme.typography.base.copy(color = colors.textRegular))\n}\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElVirtualizedSelect(\n        value = single,\n        onValueChange = { single = it },\n        options = labelOptions,\n        clearable = true,\n        labelContent = labelContent,\n        placeholder = \"Select\",\n        modifier = Modifier.width(280.dp),\n    )\n    ElVirtualizedSelectMultiple(\n        values = multiple,\n        onValueChange = { multiple = it },\n        options = labelOptions,\n        clearable = true,\n        labelContent = labelContent,\n        placeholder = \"Select\",\n        modifier = Modifier.width(320.dp),\n    )\n}",
            "Custom Loading" to "var loading by remember { mutableStateOf(true) }\nElVirtualizedSelect(\n    value = null,\n    onValueChange = {},\n    options = emptyList(),\n    loading = loading,\n    loadingContent = {\n        Row(\n            Modifier.fillMaxWidth().padding(vertical = 16.dp),\n            horizontalArrangement = Arrangement.Center,\n            verticalAlignment = Alignment.CenterVertically,\n        ) {\n            ElIcon(ElIcons.Loading, size = 20.dp, tint = colors.primary, spin = true)\n            BasicText(\"Loading states...\", modifier = Modifier.padding(start = 8.dp), style = theme.typography.small)\n        }\n    },\n    placeholder = \"Open for custom loading\",\n    modifier = Modifier.width(300.dp),\n)\nDemoRow { ElButton(text = \"Toggle loading\", onClick = { loading = !loading }) }",
            "Custom Tag" to "val tagOptions = remember {\n    listOf(\"red\", \"orange\", \"yellow\", \"green\", \"cyan\", \"blue\", \"purple\")\n        .map { ElSelectOption(it, it) }\n}\nvar values by remember { mutableStateOf(tagOptions.map { it.value }) }\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = tagOptions,\n    tagContent = { option -> ElTag(option.label, type = ElType.Success, size = ElSize.Small) },\n    placeholder = \"Select colors\",\n    modifier = Modifier.width(300.dp),\n)",
            "Custom Width" to "var value by remember { mutableStateOf<String?>(null) }\nval longOptions = remember {\n    (1..1000).map { index -> ElSelectOption(\"item-\$index\", \"Option \$index \${\"-\".repeat((index % 20) + 1)}\") }\n}\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElVirtualizedSelect(\n        value = value,\n        onValueChange = { value = it },\n        options = longOptions,\n        fitInputWidth = false,\n        placeholder = \"Dropdown width: default\",\n        modifier = Modifier.width(240.dp),\n    )\n    ElVirtualizedSelect(\n        value = value,\n        onValueChange = { value = it },\n        options = longOptions,\n        fitInputWidth = true,\n        placeholder = \"Dropdown width: fit input\",\n        modifier = Modifier.width(240.dp),\n    )\n    ElVirtualizedSelect(\n        value = value,\n        onValueChange = { value = it },\n        options = longOptions,\n        dropdownWidth = 440.dp,\n        placeholder = \"Dropdown width: 440dp\",\n        modifier = Modifier.width(240.dp),\n    )\n}",
            "Customized option renderer" to "var value by remember { mutableStateOf<String?>(null) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = options,\n    optionContent = { option, _ ->\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n            BasicText(option.label, style = theme.typography.base)\n            BasicText(option.value, style = theme.typography.small.copy(color = colors.textSecondary))\n        }\n    },\n    placeholder = \"Custom option\",\n    modifier = Modifier.width(300.dp),\n)",
            "Disabled selector and select options" to "val disabledOptions = remember {\n    options.take(100).mapIndexed { index, option -> if (index % 10 == 0) option.copy(disabled = true) else option }\n}\nvar values by remember { mutableStateOf(emptyList<String>()) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElVirtualizedSelectMultiple(\n        values = values,\n        onValueChange = { values = it },\n        options = disabledOptions,\n        filterable = true,\n        placeholder = \"Some options are disabled\",\n        modifier = Modifier.width(300.dp),\n    )\n    ElVirtualizedSelectMultiple(\n        values = values,\n        onValueChange = { values = it },\n        options = disabledOptions,\n        disabled = true,\n        placeholder = \"Disabled select\",\n        modifier = Modifier.width(300.dp),\n    )\n}",
            "Empty Values" to "val emptyOptions = remember { listOf(ElSelectOption(\"\", \"All\")) + options.take(100) }\nvar value by remember { mutableStateOf<String?>(\"\") }\nvar cleared by remember { mutableStateOf(false) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = emptyOptions,\n    emptyValues = listOf(null),\n    valueOnClear = null,\n    clearable = true,\n    onClear = { cleared = true },\n    placeholder = \"Select\",\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(if (cleared) \"Clear value: null\" else \"Selected: \${value?.ifBlank { \"All\" } ?: \"-\"}\")",
            "Filterable multi-select" to "var values by remember { mutableStateOf(listOf(\"item-3\")) }\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = options,\n    filterable = true,\n    placeholder = \"Type to filter\",\n    modifier = Modifier.width(300.dp),\n)",
            "Footer of the dropdown" to "var footerOptions by remember { mutableStateOf(virtualOptions(100)) }\nvar value by remember { mutableStateOf<String?>(\"item-1\") }\nvar adding by remember { mutableStateOf(false) }\nvar name by remember { mutableStateOf(\"\") }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = footerOptions,\n    footer = {\n        if (!adding) {\n            ElButton(text = \"Add an option\", textButton = true, bg = true, size = ElSize.Small, onClick = { adding = true })\n        } else {\n            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n                ElInput(value = name, onValueChange = { name = it }, placeholder = \"input option name\", size = ElSize.Small)\n                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {\n                    ElButton(text = \"confirm\", type = ElType.Primary, size = ElSize.Small, onClick = {\n                        if (name.isNotBlank()) {\n                            footerOptions = footerOptions + ElSelectOption(\"custom-\${footerOptions.size}\", name)\n                            name = \"\"\n                            adding = false\n                        }\n                    })\n                    ElButton(text = \"cancel\", size = ElSize.Small, onClick = { name = \"\"; adding = false })\n                }\n            }\n        }\n    },\n    placeholder = \"Select\",\n    modifier = Modifier.width(300.dp),\n)",
            "Header of the dropdown" to "val headerOptions = remember { options.take(50) }\nvar values by remember { mutableStateOf(emptyList<String>()) }\nval allChecked = values.size == headerOptions.size\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = headerOptions,\n    collapseTags = true,\n    maxCollapseTags = 1,\n    header = {\n        ElCheckbox(\n            checked = allChecked,\n            indeterminate = values.isNotEmpty() && !allChecked,\n            onCheckedChange = { checked ->\n                values = if (checked) headerOptions.map { it.value } else emptyList()\n            },\n            label = \"All\",\n        )\n    },\n    placeholder = \"Select\",\n    modifier = Modifier.width(300.dp),\n)",
            "Hide extra tags when the selected items are too many" to "var values by remember { mutableStateOf((1..6).map { \"item-\$it\" }) }\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = options,\n    collapseTags = true,\n    maxCollapseTags = 1,\n    placeholder = \"Please select\",\n    modifier = Modifier.width(300.dp),\n)\nDemoHint(\"Selected: \${values.size}\")",
            "Multi select" to "var values by remember { mutableStateOf(listOf(\"item-1\", \"item-2\")) }\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = options,\n    placeholder = \"Please select\",\n    modifier = Modifier.width(320.dp),\n)\nDemoHint(\"Selected: \${values.size}\")",
            "Option Grouping" to "var value by remember { mutableStateOf<String?>(null) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = groupedOptions,\n    filterable = true,\n    placeholder = \"Grouped options\",\n    modifier = Modifier.width(300.dp),\n)",
            "Remote search" to "val scope = rememberCoroutineScope()\nvar remoteOptions by remember { mutableStateOf(emptyList<ElSelectOption<String>>()) }\nvar values by remember { mutableStateOf(emptyList<String>()) }\nvar loading by remember { mutableStateOf(false) }\nfun remote(query: String) {\n    scope.launch {\n        if (query.isBlank()) {\n            remoteOptions = emptyList()\n            loading = false\n        } else {\n            loading = true\n            delay(250)\n            remoteOptions = virtualStates.filter { it.contains(query, ignoreCase = true) }\n                .map { ElSelectOption(\"value:\$it\", \"label:\$it\") }\n            loading = false\n        }\n    }\n}\nElVirtualizedSelectMultiple(\n    values = values,\n    onValueChange = { values = it },\n    options = remoteOptions,\n    filterable = true,\n    remote = true,\n    remoteMethod = ::remote,\n    loading = loading,\n    clearable = true,\n    placeholder = \"Please enter a keyword\",\n    modifier = Modifier.width(300.dp),\n)",
            "Sizes" to "var value by remember { mutableStateOf<String?>(null) }\nColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {\n    ElVirtualizedSelect(value, { value = it }, options, size = ElSize.Large, modifier = Modifier.width(280.dp))\n    ElVirtualizedSelect(value, { value = it }, options, modifier = Modifier.width(280.dp))\n    ElVirtualizedSelect(value, { value = it }, options, size = ElSize.Small, modifier = Modifier.width(280.dp))\n}",
            "Use value-key attribute" to "val valueOptions = remember {\n    (1..1000).map { index ->\n        ElSelectOption(VirtualValueKey(\"Option \$index\", \"test \${index % 3}\"), \"Option \$index\")\n    }\n}\nvar value by remember { mutableStateOf<VirtualValueKey?>(VirtualValueKey(\"Option 1\", \"test 0\")) }\nElVirtualizedSelect(\n    value = value,\n    onValueChange = { value = it },\n    options = valueOptions,\n    valueKey = { it.name },\n    placeholder = \"Select\",\n    modifier = Modifier.width(280.dp),\n)\nDemoHint(\"Selected: \${value?.name ?: \"-\"} (\${value?.test ?: \"-\"})\")",
