            "Multi-line watermark" to "ElWatermark(\n    text = \"Element Plus\\nKMP\",\n    color = LocalElTheme.current.colors.primary.copy(alpha = 0.18f),\n    rotate = -20f,\n    gapX = 80.dp,\n    gapY = 70.dp,\n    modifier = Modifier.fillMaxWidth().height(220.dp),\n) {\n    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {\n        BasicText(\"Multi-line watermark\", style = LocalElTheme.current.typography.medium)\n    }\n}",
            "Offset" to "ElWatermark(\n    text = \"Offset\",\n    offsetX = 40.dp,\n    offsetY = 24.dp,\n    color = colors.warning.copy(alpha = 0.2f),\n    rotate = -22f,\n    gapX = 100.dp,\n    gapY = 80.dp,\n    modifier = Modifier.fillMaxWidth().height(200.dp),\n) {\n    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {\n        BasicText(\"Offset watermark\", style = theme.typography.medium)\n    }\n}",
        ),
    )

    fun find(path: String, title: String): String? = sources[path]?.get(title)
}
